#include <print>
#include <string>

void by_value(std::string s) {
    s += "再加一句";
    std::println("  传值改完: {}", s);
}

void by_const_ref(const std::string& s) {
    s += "再加一句";   // 报错第一行说 no match for operator+=
    std::println("  传引用改完: {}", s);
}

int main() {
    std::string long_text = "这是一条很长的弹幕……";
    by_value(long_text);
    by_const_ref(long_text);
    by_value(std::move(long_text));
    std::println("原件还在: {}", long_text);
    return 0;
}

