#include <print>
#include <string>

void by_value(std::string s) {
    std::println("{}", s);
}
void by_const_ref(const std::string& s) {
    std::println("{}", s.size());
}

int main() {
    std::string t = "a";
    by_value(t);
    by_const_ref(t);
    return 0;
}

