#  include < print >
#  include < string >
void  take_by_copy ( std :: string  buf )
{
  buf  +=  "追加一点东西" ;
  std :: println ( "  {}" , buf ) ;
}
void  look_only ( const std :: string &  buf )
{
  buf  +=  "追加一点东西" ;  // 编译器说不许写只读的东西
  std :: println ( "  {}" , buf ) ;
}
int  main ( )
{
  std :: string  line  =  "很长的一段字" ;
  take_by_copy ( line ) ;
  look_only ( line ) ;
  take_by_copy ( std :: move ( line ) ) ;
}
